const OPOPL_INITIAL_QUESTIONS = [{"id":"ce-001","topicId":"t1","topic":"Tema 1 · Constitución Española de 1978 y Título Preliminar","text":"¿Cuántos artículos contiene la Constitución Española de 1978?","options":["159","169","169 más un artículo adicional","170"],"correct":1,"explanation":"La Constitución se compone de 169 artículos.","reference":"Estructura CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; contraste BOE cuando indicado"},{"id":"ce-002","topicId":"t1","topic":"Tema 1 · Constitución Española de 1978 y Título Preliminar","text":"¿En qué fecha fue ratificada la Constitución por referéndum?","options":["31 de octubre de 1978","27 de diciembre de 1978","6 de diciembre de 1978","29 de diciembre de 1978"],"correct":2,"explanation":"El referéndum de ratificación tuvo lugar el 6 de diciembre de 1978.","reference":"Proceso constituyente","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; contraste BOE cuando indicado"},{"id":"ce-003","topicId":"t1","topic":"Tema 1 · Constitución Española de 1978 y Título Preliminar","text":"¿Cuándo entró en vigor la Constitución Española?","options":["27 de diciembre de 1978","29 de diciembre de 1978","6 de diciembre de 1978","1 de enero de 1979"],"correct":1,"explanation":"Entró en vigor el mismo día de su publicación en el BOE: 29 de diciembre de 1978.","reference":"Disposición final CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; contraste BOE cuando indicado"},{"id":"ce-004","topicId":"t1","topic":"Tema 1 · Constitución Española de 1978 y Título Preliminar","text":"¿Qué artículos comprende el Título Preliminar?","options":["1 a 8","1 a 9","1 a 10","2 a 9"],"correct":1,"explanation":"El Título Preliminar comprende los artículos 1 a 9.","reference":"Título Preliminar CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; contraste BOE cuando indicado"},{"id":"ce-005","topicId":"t1","topic":"Tema 1 · Constitución Española de 1978 y Título Preliminar","text":"Según el artículo 1.1, España se constituye en un Estado…","options":["Federal, social y parlamentario","Social y democrático de Derecho","Autonómico y presidencialista","Democrático y confederal"],"correct":1,"explanation":"El artículo 1.1 define a España como Estado social y democrático de Derecho.","reference":"Art. 1.1 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; contraste BOE cuando indicado"},{"id":"ce-006","topicId":"t1","topic":"Tema 1 · Constitución Española de 1978 y Título Preliminar","text":"¿En quién reside la soberanía nacional?","options":["En las Cortes Generales","En el Rey","En el pueblo español","En el Gobierno"],"correct":2,"explanation":"La soberanía nacional reside en el pueblo español, del que emanan los poderes del Estado.","reference":"Art. 1.2 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; contraste BOE cuando indicado"},{"id":"ce-007","topicId":"t1","topic":"Tema 1 · Constitución Española de 1978 y Título Preliminar","text":"¿Cuál es la forma política del Estado español?","options":["República parlamentaria","Monarquía absoluta","Monarquía parlamentaria","Monarquía constitucional presidencialista"],"correct":2,"explanation":"El artículo 1.3 establece la Monarquía parlamentaria.","reference":"Art. 1.3 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; contraste BOE cuando indicado"},{"id":"ce-008","topicId":"t1","topic":"Tema 1 · Constitución Española de 1978 y Título Preliminar","text":"¿Qué garantiza el artículo 2 de la Constitución?","options":["La autonomía de todas las provincias","La indisoluble unidad de la Nación española y el derecho a la autonomía de nacionalidades y regiones","La independencia de las nacionalidades históricas","La soberanía de las comunidades autónomas"],"correct":1,"explanation":"El artículo 2 combina la unidad de la Nación española con la autonomía y solidaridad.","reference":"Art. 2 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; contraste BOE cuando indicado"},{"id":"ce-009","topicId":"t1","topic":"Tema 1 · Constitución Española de 1978 y Título Preliminar","text":"¿Cuál es la lengua española oficial del Estado?","options":["El castellano","El castellano y todas las lenguas cooficiales por igual en todo el Estado","La lengua que determine cada comunidad autónoma","El español y el inglés"],"correct":0,"explanation":"El castellano es la lengua española oficial del Estado; todos los españoles tienen el deber de conocerla y el derecho a usarla.","reference":"Art. 3.1 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; contraste BOE cuando indicado"},{"id":"ce-010","topicId":"t1","topic":"Tema 1 · Constitución Española de 1978 y Título Preliminar","text":"¿Qué artículo establece la capital del Estado?","options":["Artículo 3","Artículo 4","Artículo 5","Artículo 6"],"correct":2,"explanation":"El artículo 5 establece que la capital del Estado es la villa de Madrid.","reference":"Art. 5 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; contraste BOE cuando indicado"},{"id":"ce-011","topicId":"t2","topic":"Tema 2 · Derechos y deberes fundamentales","text":"¿Qué artículo proclama la igualdad ante la ley?","options":["Artículo 9","Artículo 10","Artículo 14","Artículo 15"],"correct":2,"explanation":"El artículo 14 reconoce la igualdad ante la ley y prohíbe la discriminación por los motivos que enumera.","reference":"Art. 14 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; contraste BOE cuando indicado"},{"id":"ce-012","topicId":"t2","topic":"Tema 2 · Derechos y deberes fundamentales","text":"¿Qué artículo reconoce el derecho a la vida y a la integridad física y moral?","options":["Artículo 14","Artículo 15","Artículo 16","Artículo 17"],"correct":1,"explanation":"El derecho a la vida y a la integridad física y moral está reconocido en el artículo 15.","reference":"Art. 15 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; contraste BOE cuando indicado"},{"id":"ce-013","topicId":"t2","topic":"Tema 2 · Derechos y deberes fundamentales","text":"¿Qué artículo garantiza la libertad ideológica, religiosa y de culto?","options":["Artículo 15","Artículo 16","Artículo 17","Artículo 18"],"correct":1,"explanation":"El artículo 16 garantiza la libertad ideológica, religiosa y de culto de los individuos y las comunidades.","reference":"Art. 16 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; contraste BOE cuando indicado"},{"id":"ce-014","topicId":"t2","topic":"Tema 2 · Derechos y deberes fundamentales","text":"¿Cuál es la duración máxima ordinaria de la detención preventiva según el artículo 17.2?","options":["24 horas","48 horas","72 horas","5 días"],"correct":2,"explanation":"La detención preventiva no podrá durar más del tiempo estrictamente necesario y, en todo caso, en el plazo máximo de 72 horas el detenido debe ser puesto en libertad o a disposición judicial.","reference":"Art. 17.2 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; contraste BOE cuando indicado"},{"id":"ce-015","topicId":"t2","topic":"Tema 2 · Derechos y deberes fundamentales","text":"¿Qué artículo reconoce la inviolabilidad del domicilio?","options":["Artículo 17","Artículo 18","Artículo 19","Artículo 20"],"correct":1,"explanation":"El artículo 18.2 establece que el domicilio es inviolable, con las excepciones constitucionales.","reference":"Art. 18.2 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; contraste BOE cuando indicado"},{"id":"ce-016","topicId":"t2","topic":"Tema 2 · Derechos y deberes fundamentales","text":"¿Qué artículo reconoce la libertad de residencia y circulación por el territorio nacional?","options":["Artículo 18","Artículo 19","Artículo 20","Artículo 21"],"correct":1,"explanation":"La libertad de residencia y circulación se recoge en el artículo 19.","reference":"Art. 19 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; contraste BOE cuando indicado"},{"id":"ce-017","topicId":"t2","topic":"Tema 2 · Derechos y deberes fundamentales","text":"¿Qué artículo reconoce el derecho de reunión pacífica y sin armas?","options":["Artículo 20","Artículo 21","Artículo 22","Artículo 23"],"correct":1,"explanation":"El artículo 21 reconoce el derecho de reunión pacífica y sin armas; su ejercicio no necesita autorización previa.","reference":"Art. 21 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; contraste BOE cuando indicado"},{"id":"ce-018","topicId":"t2","topic":"Tema 2 · Derechos y deberes fundamentales","text":"¿Qué artículo reconoce la tutela judicial efectiva?","options":["Artículo 23","Artículo 24","Artículo 25","Artículo 26"],"correct":1,"explanation":"El artículo 24 reconoce el derecho a obtener tutela efectiva de jueces y tribunales en el ejercicio de derechos e intereses legítimos.","reference":"Art. 24 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; contraste BOE cuando indicado"},{"id":"ce-019","topicId":"t2","topic":"Tema 2 · Derechos y deberes fundamentales","text":"¿Qué artículo reconoce la libertad sindical y el derecho de huelga?","options":["Artículo 27","Artículo 28","Artículo 29","Artículo 30"],"correct":1,"explanation":"Ambos derechos se recogen en el artículo 28, en sus apartados 1 y 2 respectivamente.","reference":"Art. 28 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; contraste BOE cuando indicado"},{"id":"ce-020","topicId":"t2","topic":"Tema 2 · Derechos y deberes fundamentales","text":"¿En qué artículo se regula el derecho de petición?","options":["Artículo 27","Artículo 28","Artículo 29","Artículo 30"],"correct":2,"explanation":"El derecho de petición individual y colectiva por escrito se reconoce en el artículo 29.","reference":"Art. 29 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; contraste BOE cuando indicado"},{"id":"ce-021","topicId":"t3","topic":"Tema 3 · Garantías y suspensión de derechos","text":"¿Qué artículos integran la Sección 1.ª del Capítulo II del Título I?","options":["10 a 14","14 a 29","15 a 29","30 a 38"],"correct":2,"explanation":"La Sección 1.ª comprende los artículos 15 a 29. El artículo 14 está en el Capítulo II, pero fuera de las secciones.","reference":"Arts. 14-29 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; contraste BOE cuando indicado"},{"id":"ce-022","topicId":"t3","topic":"Tema 3 · Garantías y suspensión de derechos","text":"¿Qué derechos pueden ser objeto de tutela mediante el procedimiento preferente y sumario del artículo 53.2?","options":["Todos los del Título I","Los del artículo 14 y los de la Sección 1.ª del Capítulo II","Solo los artículos 15 a 29","Solo los principios rectores"],"correct":1,"explanation":"El artículo 53.2 contempla la tutela de las libertades y derechos del artículo 14 y de la Sección 1.ª del Capítulo II.","reference":"Art. 53.2 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; contraste BOE cuando indicado"},{"id":"ce-023","topicId":"t3","topic":"Tema 3 · Garantías y suspensión de derechos","text":"¿Ante qué órgano se interpone el recurso de amparo constitucional?","options":["Tribunal Supremo","Audiencia Nacional","Tribunal Constitucional","Consejo General del Poder Judicial"],"correct":2,"explanation":"El recurso de amparo es competencia del Tribunal Constitucional.","reference":"Art. 53.2 y 161.1.b CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; contraste BOE cuando indicado"},{"id":"ce-024","topicId":"t3","topic":"Tema 3 · Garantías y suspensión de derechos","text":"¿Qué institución es el alto comisionado de las Cortes Generales para la defensa de los derechos del Título I?","options":["Fiscal General del Estado","Defensor del Pueblo","Consejo de Estado","Tribunal de Cuentas"],"correct":1,"explanation":"El artículo 54 configura al Defensor del Pueblo como alto comisionado de las Cortes Generales.","reference":"Art. 54 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; contraste BOE cuando indicado"},{"id":"ce-025","topicId":"t3","topic":"Tema 3 · Garantías y suspensión de derechos","text":"¿Qué ley orgánica regula el Defensor del Pueblo?","options":["LO 2/1979","LO 3/1981","LO 4/1981","LO 5/1985"],"correct":1,"explanation":"La institución se desarrolla mediante la Ley Orgánica 3/1981, de 6 de abril.","reference":"Art. 54 CE; LO 3/1981","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; contraste BOE cuando indicado"},{"id":"ce-026","topicId":"t3","topic":"Tema 3 · Garantías y suspensión de derechos","text":"¿Qué estados permiten la suspensión general de determinados derechos del artículo 55.1?","options":["Alarma y excepción","Excepción y sitio","Alarma y sitio","Solo sitio"],"correct":1,"explanation":"El artículo 55.1 vincula la suspensión general de los derechos enumerados a los estados de excepción o de sitio, no al de alarma.","reference":"Art. 55.1 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; contraste BOE cuando indicado"},{"id":"ce-027","topicId":"t3","topic":"Tema 3 · Garantías y suspensión de derechos","text":"¿Qué derecho del artículo 17 queda exceptuado de suspensión en el estado de excepción?","options":["La libertad personal","El derecho a ser informado de las razones de detención","La garantía del artículo 17.3","La duración máxima de la detención preventiva"],"correct":2,"explanation":"El último inciso del artículo 55.1 exceptúa la garantía del artículo 17.3 para el supuesto de declaración del estado de excepción.","reference":"Art. 55.1 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; contraste BOE cuando indicado"},{"id":"ce-028","topicId":"t3","topic":"Tema 3 · Garantías y suspensión de derechos","text":"¿Quién declara el estado de alarma?","options":["El Congreso por mayoría absoluta","El Gobierno mediante decreto acordado en Consejo de Ministros","El Rey a propuesta del Senado","El Tribunal Constitucional"],"correct":1,"explanation":"El estado de alarma lo declara el Gobierno mediante decreto acordado en Consejo de Ministros, dando cuenta al Congreso.","reference":"Art. 116.2 CE; LO 4/1981","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; contraste BOE cuando indicado"},{"id":"ce-029","topicId":"t3","topic":"Tema 3 · Garantías y suspensión de derechos","text":"¿Cuál es la duración máxima inicial del estado de alarma?","options":["10 días","15 días","30 días","60 días"],"correct":1,"explanation":"El decreto de declaración no puede exceder de 15 días; la prórroga requiere autorización del Congreso.","reference":"Art. 116.2 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; contraste BOE cuando indicado"},{"id":"ce-030","topicId":"t3","topic":"Tema 3 · Garantías y suspensión de derechos","text":"¿Quién declara el estado de sitio?","options":["El Gobierno por decreto","El Rey previa autorización del Senado","El Congreso de los Diputados por mayoría absoluta, a propuesta exclusiva del Gobierno","El Consejo de Ministros con ratificación posterior"],"correct":2,"explanation":"El Congreso declara el estado de sitio por mayoría absoluta, a propuesta exclusiva del Gobierno.","reference":"Art. 116.4 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; contraste BOE cuando indicado"},{"id":"ce-031","topicId":"t1","topic":"Tema 1 · Constitución Española de 1978 y Título Preliminar","text":"¿Qué texto de 1808 se identifica en los apuntes como una carta otorgada de carácter afrancesado?","options":["Estatuto Real","Estatuto de Bayona","Constitución de 1812","Constitución de 1837"],"correct":1,"explanation":"Los apuntes identifican el Estatuto de Bayona de 1808 como carta otorgada de carácter afrancesado.","reference":"Antecedentes constitucionales","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; pregunta elaborada a partir del epígrafe indicado"},{"id":"ce-032","topicId":"t1","topic":"Tema 1 · Constitución Española de 1978 y Título Preliminar","text":"¿Qué Constitución es conocida popularmente como «La Pepa»?","options":["La de 1837","La de 1845","La de 1812","La de 1869"],"correct":2,"explanation":"La Constitución de 1812 fue promulgada el 19 de marzo y es conocida como «La Pepa».","reference":"Antecedentes constitucionales","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; pregunta elaborada a partir del epígrafe indicado"},{"id":"ce-033","topicId":"t1","topic":"Tema 1 · Constitución Española de 1978 y Título Preliminar","text":"¿En qué fecha se celebraron las primeras elecciones democráticas de la Transición que recogen los apuntes?","options":["20 de noviembre de 1975","4 de enero de 1977","15 de junio de 1977","6 de diciembre de 1978"],"correct":2,"explanation":"Los apuntes sitúan las primeras elecciones democráticas el 15 de junio de 1977.","reference":"Proceso constituyente","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; pregunta elaborada a partir del epígrafe indicado"},{"id":"ce-034","topicId":"t1","topic":"Tema 1 · Constitución Española de 1978 y Título Preliminar","text":"¿Qué día fue sancionada y promulgada la Constitución por el Rey?","options":["31 de octubre de 1978","6 de diciembre de 1978","27 de diciembre de 1978","29 de diciembre de 1978"],"correct":2,"explanation":"El Congreso y el Senado aprobaron el texto el 31 de octubre; el pueblo lo ratificó el 6 de diciembre; el Rey lo sancionó y promulgó el 27 de diciembre.","reference":"Proceso constituyente","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; pregunta elaborada a partir del epígrafe indicado"},{"id":"ce-035","topicId":"t1","topic":"Tema 1 · Constitución Española de 1978 y Título Preliminar","text":"¿Cuántas disposiciones adicionales contiene la Constitución?","options":["Una","Cuatro","Nueve","Diez"],"correct":1,"explanation":"La estructura constitucional comprende cuatro disposiciones adicionales.","reference":"Estructura CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; pregunta elaborada a partir del epígrafe indicado"},{"id":"ce-036","topicId":"t1","topic":"Tema 1 · Constitución Española de 1978 y Título Preliminar","text":"¿Cuántas disposiciones transitorias contiene la Constitución?","options":["Cuatro","Una","Nueve","Dos"],"correct":2,"explanation":"La Constitución contiene nueve disposiciones transitorias.","reference":"Estructura CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; pregunta elaborada a partir del epígrafe indicado"},{"id":"ce-037","topicId":"t1","topic":"Tema 1 · Constitución Española de 1978 y Título Preliminar","text":"¿Qué título constitucional regula la organización territorial del Estado?","options":["Título VI","Título VII","Título VIII","Título IX"],"correct":2,"explanation":"El Título VIII, artículos 137 a 158, se dedica a la organización territorial del Estado.","reference":"Título VIII CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; pregunta elaborada a partir del epígrafe indicado"},{"id":"ce-038","topicId":"t1","topic":"Tema 1 · Constitución Española de 1978 y Título Preliminar","text":"¿Qué título regula la reforma constitucional?","options":["Título VIII","Título IX","Título X","Título V"],"correct":2,"explanation":"El Título X, artículos 166 a 169, regula la reforma constitucional.","reference":"Título X CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; pregunta elaborada a partir del epígrafe indicado"},{"id":"ce-039","topicId":"t1","topic":"Tema 1 · Constitución Española de 1978 y Título Preliminar","text":"¿Qué disposición constitucional establece la entrada en vigor el mismo día de la publicación oficial?","options":["Disposición adicional primera","Disposición transitoria novena","Disposición derogatoria","Disposición final"],"correct":3,"explanation":"La disposición final establece la entrada en vigor el mismo día de la publicación del texto oficial en el BOE.","reference":"Disposición final CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; pregunta elaborada a partir del epígrafe indicado"},{"id":"ce-040","topicId":"t1","topic":"Tema 1 · Constitución Española de 1978 y Título Preliminar","text":"¿Qué título comprende los artículos 66 a 96?","options":["Título II: De la Corona","Título III: De las Cortes Generales","Título IV: Del Gobierno y de la Administración","Título V: Relaciones entre Gobierno y Cortes"],"correct":1,"explanation":"El Título III regula las Cortes Generales y comprende los artículos 66 a 96.","reference":"Título III CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; pregunta elaborada a partir del epígrafe indicado"},{"id":"ce-041","topicId":"t2","topic":"Tema 2 · Derechos y deberes fundamentales","text":"¿Qué derecho recoge el artículo 20.1.a) de la Constitución?","options":["Libertad de cátedra exclusivamente","Expresar y difundir libremente pensamientos, ideas y opiniones","Derecho de reunión","Derecho de petición"],"correct":1,"explanation":"El artículo 20.1.a) reconoce el derecho a expresar y difundir libremente pensamientos, ideas y opiniones mediante la palabra, el escrito o cualquier otro medio de reproducción.","reference":"Art. 20.1.a) CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; pregunta elaborada a partir del epígrafe indicado"},{"id":"ce-042","topicId":"t2","topic":"Tema 2 · Derechos y deberes fundamentales","text":"¿Qué derecho reconoce el artículo 22 de la Constitución?","options":["Derecho de asociación","Derecho de reunión","Derecho de participación política","Libertad sindical"],"correct":0,"explanation":"El artículo 22 reconoce el derecho de asociación.","reference":"Art. 22 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; pregunta elaborada a partir del epígrafe indicado"},{"id":"ce-043","topicId":"t2","topic":"Tema 2 · Derechos y deberes fundamentales","text":"¿Qué reconoce el artículo 23.1 de la Constitución?","options":["El derecho a la educación","El derecho a participar en los asuntos públicos directamente o por representantes","El derecho de petición","La libertad de empresa"],"correct":1,"explanation":"El artículo 23.1 reconoce la participación en los asuntos públicos, directamente o por medio de representantes libremente elegidos en elecciones periódicas por sufragio universal.","reference":"Art. 23.1 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; pregunta elaborada a partir del epígrafe indicado"},{"id":"ce-044","topicId":"t2","topic":"Tema 2 · Derechos y deberes fundamentales","text":"Según el artículo 25.1, nadie puede ser condenado o sancionado por acciones u omisiones que, al producirse, no constituyan…","options":["Una infracción administrativa grave","Delito o falta según la legislación vigente en aquel momento","Una infracción prevista en un reglamento posterior","Una conducta contraria a la moral"],"correct":1,"explanation":"El artículo 25.1 consagra el principio de legalidad sancionadora: la conducta debe constituir delito o infracción según la legislación vigente en el momento de producirse.","reference":"Art. 25.1 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; pregunta elaborada a partir del epígrafe indicado"},{"id":"ce-045","topicId":"t2","topic":"Tema 2 · Derechos y deberes fundamentales","text":"¿Qué prohíbe expresamente el artículo 26 de la Constitución?","options":["Los tribunales consuetudinarios","Los tribunales de honor en el ámbito de la Administración civil y de las organizaciones profesionales","Los tribunales militares","Los jurados populares"],"correct":1,"explanation":"El artículo 26 prohíbe los tribunales de honor en el ámbito de la Administración civil y de las organizaciones profesionales.","reference":"Art. 26 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; pregunta elaborada a partir del epígrafe indicado"},{"id":"ce-046","topicId":"t2","topic":"Tema 2 · Derechos y deberes fundamentales","text":"¿Qué establece el artículo 27.1?","options":["La enseñanza básica es voluntaria y gratuita","Todos tienen derecho a la educación y se reconoce la libertad de enseñanza","La educación corresponde exclusivamente al Estado","La universidad es obligatoria"],"correct":1,"explanation":"El artículo 27.1 reconoce el derecho de todos a la educación y la libertad de enseñanza.","reference":"Art. 27.1 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; pregunta elaborada a partir del epígrafe indicado"},{"id":"ce-047","topicId":"t2","topic":"Tema 2 · Derechos y deberes fundamentales","text":"¿Qué apartado del artículo 28 reconoce el derecho de huelga de los trabajadores?","options":["28.1","28.2","28.3","28.4"],"correct":1,"explanation":"El artículo 28.2 reconoce el derecho de huelga de los trabajadores para la defensa de sus intereses.","reference":"Art. 28.2 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; pregunta elaborada a partir del epígrafe indicado"},{"id":"ce-048","topicId":"t2","topic":"Tema 2 · Derechos y deberes fundamentales","text":"¿Qué establece el artículo 30.1?","options":["Todos tienen el deber de pagar tributos","Los españoles tienen el derecho y el deber de defender a España","Todos tienen derecho al trabajo","La mayoría de edad se alcanza a los 21 años"],"correct":1,"explanation":"El artículo 30.1 establece el derecho y el deber de los españoles de defender a España.","reference":"Art. 30.1 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; pregunta elaborada a partir del epígrafe indicado"},{"id":"ce-049","topicId":"t2","topic":"Tema 2 · Derechos y deberes fundamentales","text":"¿Qué principios debe respetar el sistema tributario según el artículo 31.1?","options":["Igualdad y progresividad, sin alcance confiscatorio","Proporcionalidad y uniformidad absoluta","Capacidad económica exclusivamente","Progresividad y carácter confiscatorio"],"correct":0,"explanation":"El artículo 31.1 dispone que todos contribuirán según su capacidad económica mediante un sistema tributario justo inspirado en igualdad y progresividad, que en ningún caso tendrá alcance confiscatorio.","reference":"Art. 31.1 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; pregunta elaborada a partir del epígrafe indicado"},{"id":"ce-050","topicId":"t2","topic":"Tema 2 · Derechos y deberes fundamentales","text":"¿Qué reconoce el artículo 33.1?","options":["La libertad sindical","El derecho a la propiedad privada y a la herencia","La libertad de empresa","El derecho de fundación"],"correct":1,"explanation":"El artículo 33.1 reconoce el derecho a la propiedad privada y a la herencia.","reference":"Art. 33.1 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, julio 2023; pregunta elaborada a partir del epígrafe indicado"},{"id":"ce-051","topicId":"t3","topic":"Tema 3 · Garantías y suspensión de derechos","text":"Según el artículo 53.3, ¿qué función cumplen los principios reconocidos en el Capítulo III del Título I?","options":["Son directamente recurribles en amparo constitucional","Informan la legislación positiva, la práctica judicial y la actuación de los poderes públicos","Carecen de eficacia jurídica","Vinculan exclusivamente a las comunidades autónomas"],"correct":1,"explanation":"El artículo 53.3 atribuye a esos principios una función informadora; solo podrán alegarse ante la jurisdicción ordinaria conforme a las leyes que los desarrollen.","reference":"Art. 53.3 CE","status":"revisada · contraste normativo BOE","source":"Temario AESPOL, Temas 1-2-3 (julio 2023) + contraste con legislación consolidada BOE"},{"id":"ce-052","topicId":"t3","topic":"Tema 3 · Garantías y suspensión de derechos","text":"Además de defender los derechos del Título I, ¿qué función atribuye el artículo 54 al Defensor del Pueblo?","options":["Dirigir la Fiscalía General del Estado","Supervisar la actividad de la Administración y dar cuenta a las Cortes Generales","Anular directamente las leyes","Resolver recursos de amparo"],"correct":1,"explanation":"El Defensor del Pueblo puede supervisar la actividad de la Administración y dar cuenta de su actuación a las Cortes Generales, conforme a su ley orgánica.","reference":"Art. 54 CE; LO 3/1981","status":"revisada · contraste normativo BOE","source":"Temario AESPOL, Temas 1-2-3 (julio 2023) + contraste con legislación consolidada BOE"},{"id":"ce-053","topicId":"t3","topic":"Tema 3 · Garantías y suspensión de derechos","text":"¿Qué debe incluir la solicitud del Gobierno al Congreso para obtener autorización para declarar el estado de excepción?","options":["La relación de los derechos cuya suspensión solicita, las medidas, el ámbito territorial y la duración, entre otros extremos legales","Únicamente el nombre de la autoridad gubernativa","La relación de municipios y el presupuesto anual de cada uno","La propuesta de disolución del Congreso"],"correct":0,"explanation":"El artículo 13.2 de la LO 4/1981 exige que la solicitud incluya los efectos, los derechos cuya suspensión se solicita, las medidas, el ámbito territorial y la duración, entre otros extremos.","reference":"Art. 13.2 LO 4/1981","status":"revisada · contraste normativo BOE","source":"Temario AESPOL, Temas 1-2-3 (julio 2023) + contraste con legislación consolidada BOE"},{"id":"ce-054","topicId":"t3","topic":"Tema 3 · Garantías y suspensión de derechos","text":"¿En qué supuesto constitucional puede acordarse la suspensión individual de determinados derechos conforme al artículo 55.2?","options":["En cualquier investigación penal ordinaria","En investigaciones relacionadas con bandas armadas o elementos terroristas, en los términos establecidos por ley orgánica","Por decisión discrecional de cualquier alcalde","Durante cualquier estado de alarma"],"correct":1,"explanation":"El artículo 55.2 contempla la suspensión individual en relación con investigaciones correspondientes a la actuación de bandas armadas o elementos terroristas, con garantías legales, intervención judicial y control parlamentario.","reference":"Art. 55.2 CE","status":"revisada · contraste normativo BOE","source":"Temario AESPOL, Temas 1-2-3 (julio 2023) + contraste con legislación consolidada BOE"},{"id":"ce-055","topicId":"t3","topic":"Tema 3 · Garantías y suspensión de derechos","text":"¿Qué sucede con el Congreso de los Diputados mientras esté declarado alguno de los estados del artículo 116?","options":["Puede ser disuelto libremente por el Gobierno","No puede ser disuelto; si estuviera disuelto o hubiera expirado su mandato, sus competencias serán asumidas por la Diputación Permanente","Queda suspendido automáticamente","Sus competencias pasan al Senado"],"correct":1,"explanation":"El artículo 116.5 impide disolver el Congreso durante la vigencia de esos estados y atribuye sus competencias a la Diputación Permanente si estuviera disuelto o hubiera expirado su mandato.","reference":"Art. 116.5 CE","status":"revisada · contraste normativo BOE","source":"Temario AESPOL, Temas 1-2-3 (julio 2023) + contraste con legislación consolidada BOE"},{"id":"ce-056","topicId":"t3","topic":"Tema 3 · Garantías y suspensión de derechos","text":"¿La declaración de los estados del artículo 116 altera el principio de responsabilidad del Gobierno y de sus agentes?","options":["Sí, queda suspendido","Sí, pasa exclusivamente al Congreso","No; el artículo 116.6 mantiene el principio de responsabilidad del Gobierno y de sus agentes","Solo se mantiene durante el estado de alarma"],"correct":2,"explanation":"El artículo 116.6 establece que la declaración de los estados no modifica el principio de responsabilidad del Gobierno y de sus agentes reconocido en la Constitución y las leyes.","reference":"Art. 116.6 CE","status":"revisada · contraste normativo BOE","source":"Temario AESPOL, Temas 1-2-3 (julio 2023) + contraste con legislación consolidada BOE"},{"id":"ce-057","topicId":"t3","topic":"Tema 3 · Garantías y suspensión de derechos","text":"¿Qué criterio general impone la Ley Orgánica 4/1981 a las medidas adoptadas durante los estados excepcionales?","options":["Deben ser indefinidas para asegurar la eficacia","Deben ser estrictamente indispensables y aplicarse de forma proporcionada a las circunstancias","Pueden suspender cualquier derecho sin límite","No están sujetas a control jurisdiccional"],"correct":1,"explanation":"El artículo 1.2 de la LO 4/1981 exige que las medidas y su duración sean estrictamente indispensables y que su aplicación sea proporcionada.","reference":"Art. 1.2 LO 4/1981","status":"revisada · contraste normativo BOE","source":"Temario AESPOL, Temas 1-2-3 (julio 2023) + contraste con legislación consolidada BOE"},{"id":"ce-058","topicId":"t3","topic":"Tema 3 · Garantías y suspensión de derechos","text":"¿Desde qué momento entra en vigor la declaración de un estado excepcional según la Ley Orgánica 4/1981?","options":["Desde su aprobación por el Consejo de Ministros, aunque no se publique","Desde su publicación en el Boletín Oficial del Estado","Desde su comunicación a los ayuntamientos","Desde su ratificación por el Tribunal Constitucional"],"correct":1,"explanation":"El artículo 2 de la LO 4/1981 dispone que la declaración entra en vigor desde el instante mismo de su publicación en el BOE.","reference":"Art. 2 LO 4/1981","status":"revisada · contraste normativo BOE","source":"Temario AESPOL, Temas 1-2-3 (julio 2023) + contraste con legislación consolidada BOE"},{"id":"ce-059","topicId":"t3","topic":"Tema 3 · Garantías y suspensión de derechos","text":"¿Son impugnables judicialmente los actos y disposiciones de la Administración adoptados durante los estados excepcionales?","options":["No, quedan excluidos de todo control","Sí, en vía jurisdiccional conforme a las leyes","Solo si lo autoriza el Congreso","Únicamente ante el Tribunal Constitucional"],"correct":1,"explanation":"El artículo 3.1 de la LO 4/1981 establece que esos actos y disposiciones son impugnables en vía jurisdiccional conforme a las leyes.","reference":"Art. 3.1 LO 4/1981","status":"revisada · contraste normativo BOE","source":"Temario AESPOL, Temas 1-2-3 (julio 2023) + contraste con legislación consolidada BOE"},{"id":"ce-060","topicId":"t3","topic":"Tema 3 · Garantías y suspensión de derechos","text":"¿Puede el presidente de una comunidad autónoma solicitar al Gobierno la declaración del estado de alarma?","options":["No, nunca","Sí, cuando los supuestos del artículo 4 de la LO 4/1981 afecten exclusivamente a todo o parte de su territorio","Sí, pero solo puede declararlo el propio presidente autonómico","Solo con autorización previa del Senado"],"correct":1,"explanation":"El artículo 5 de la LO 4/1981 permite al presidente de una comunidad autónoma solicitar al Gobierno la declaración cuando concurra una alteración grave que afecte exclusivamente a todo o parte de su territorio.","reference":"Art. 5 LO 4/1981","status":"revisada · contraste normativo BOE","source":"Temario AESPOL, Temas 1-2-3 (julio 2023) + contraste con legislación consolidada BOE"},{"id":"ce-061","topicId":"t1","topic":"Tema 1 · Constitución Española de 1978 y Título Preliminar","text":"Según el artículo 9.1 de la Constitución, ¿a qué quedan sujetos los ciudadanos y los poderes públicos?","options":["Solo a las leyes orgánicas","A la Constitución y al resto del ordenamiento jurídico","A los reglamentos del Gobierno exclusivamente","A las normas autonómicas con preferencia sobre la Constitución"],"correct":1,"explanation":"El artículo 9.1 establece la sujeción de ciudadanos y poderes públicos a la Constitución y al resto del ordenamiento jurídico.","reference":"Art. 9.1 CE","status":"revisada · contraste normativo BOE","source":"Temario AESPOL, Temas 1-2-3 (julio 2023) + contraste con legislación consolidada BOE"},{"id":"ce-062","topicId":"t1","topic":"Tema 1 · Constitución Española de 1978 y Título Preliminar","text":"¿Qué mandato dirige el artículo 9.2 a los poderes públicos?","options":["Mantener las desigualdades sociales","Limitar la participación ciudadana a los procesos electorales","Promover las condiciones para que la libertad y la igualdad sean reales y efectivas, y facilitar la participación","Sustituir la iniciativa de los ciudadanos en la vida política"],"correct":2,"explanation":"El artículo 9.2 ordena promover las condiciones para que libertad e igualdad sean reales y efectivas, remover obstáculos y facilitar la participación.","reference":"Art. 9.2 CE","status":"revisada · contraste normativo BOE","source":"Temario AESPOL, Temas 1-2-3 (julio 2023) + contraste con legislación consolidada BOE"},{"id":"ce-063","topicId":"t1","topic":"Tema 1 · Constitución Española de 1978 y Título Preliminar","text":"¿Qué principio del artículo 9.3 impide aplicar retroactivamente disposiciones sancionadoras no favorables o restrictivas de derechos individuales?","options":["Jerarquía normativa","Irretroactividad de las disposiciones sancionadoras no favorables o restrictivas de derechos individuales","Publicidad de las normas","Responsabilidad de los poderes públicos"],"correct":1,"explanation":"El artículo 9.3 garantiza expresamente la irretroactividad de esas disposiciones.","reference":"Art. 9.3 CE","status":"revisada · contraste normativo BOE","source":"Temario AESPOL, Temas 1-2-3 (julio 2023) + contraste con legislación consolidada BOE"},{"id":"ce-064","topicId":"t1","topic":"Tema 1 · Constitución Española de 1978 y Título Preliminar","text":"¿Qué garantía del artículo 9.3 prohíbe que los poderes públicos actúen arbitrariamente?","options":["La interdicción de la arbitrariedad de los poderes públicos","La autonomía de las nacionalidades","La libertad de empresa","La potestad reglamentaria"],"correct":0,"explanation":"El artículo 9.3 garantiza la interdicción de la arbitrariedad de los poderes públicos.","reference":"Art. 9.3 CE","status":"revisada · contraste normativo BOE","source":"Temario AESPOL, Temas 1-2-3 (julio 2023) + contraste con legislación consolidada BOE"},{"id":"ce-065","topicId":"t1","topic":"Tema 1 · Constitución Española de 1978 y Título Preliminar","text":"¿Qué títulos integran la parte orgánica de la Constitución?","options":["Preliminar y I","Del II al X","Del I al V","Solo del VIII al X"],"correct":1,"explanation":"Según la división didáctica del temario, la parte orgánica comprende los títulos II a X.","reference":"Estructura CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, actualizado julio 2023; contenido contrastado con el texto constitucional aplicable cuando procede"},{"id":"ce-066","topicId":"t1","topic":"Tema 1 · Constitución Española de 1978 y Título Preliminar","text":"¿Qué materia regula el Título II de la Constitución?","options":["Las Cortes Generales","La Corona","El Gobierno","El Poder Judicial"],"correct":1,"explanation":"El Título II, artículos 56 a 65, regula la Corona.","reference":"Título II CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, actualizado julio 2023; contenido contrastado con el texto constitucional aplicable cuando procede"},{"id":"ce-067","topicId":"t1","topic":"Tema 1 · Constitución Española de 1978 y Título Preliminar","text":"¿Qué artículos comprende el Título III?","options":["66 a 96","97 a 107","108 a 116","117 a 127"],"correct":0,"explanation":"El Título III, dedicado a las Cortes Generales, comprende los artículos 66 a 96.","reference":"Título III CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, actualizado julio 2023; contenido contrastado con el texto constitucional aplicable cuando procede"},{"id":"ce-068","topicId":"t1","topic":"Tema 1 · Constitución Española de 1978 y Título Preliminar","text":"¿Qué materia regula el Título IV?","options":["Gobierno y Administración","Relaciones entre Gobierno y Cortes","Poder Judicial","Economía y Hacienda"],"correct":0,"explanation":"El Título IV regula el Gobierno y la Administración.","reference":"Título IV CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, actualizado julio 2023; contenido contrastado con el texto constitucional aplicable cuando procede"},{"id":"ce-069","topicId":"t1","topic":"Tema 1 · Constitución Española de 1978 y Título Preliminar","text":"¿Qué artículos comprende el Título V?","options":["97 a 107","108 a 116","117 a 127","128 a 136"],"correct":1,"explanation":"El Título V regula las relaciones entre el Gobierno y las Cortes Generales, artículos 108 a 116.","reference":"Título V CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, actualizado julio 2023; contenido contrastado con el texto constitucional aplicable cuando procede"},{"id":"ce-070","topicId":"t1","topic":"Tema 1 · Constitución Española de 1978 y Título Preliminar","text":"¿Qué artículos comprende el Título VIII, dedicado a la organización territorial del Estado?","options":["97 a 107","117 a 127","137 a 158","159 a 165"],"correct":2,"explanation":"El Título VIII comprende los artículos 137 a 158.","reference":"Título VIII CE","status":"revisada · contraste normativo BOE","source":"Temario AESPOL, Temas 1-2-3 (julio 2023) + contraste con legislación consolidada BOE"},{"id":"ce-071","topicId":"t1","topic":"Tema 1 · Constitución Española de 1978 y Título Preliminar","text":"¿Qué título está dedicado al Tribunal Constitucional?","options":["VII","VIII","IX","X"],"correct":2,"explanation":"El Título IX regula el Tribunal Constitucional, artículos 159 a 165.","reference":"Título IX CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, actualizado julio 2023; contenido contrastado con el texto constitucional aplicable cuando procede"},{"id":"ce-072","topicId":"t1","topic":"Tema 1 · Constitución Española de 1978 y Título Preliminar","text":"¿A qué preceptos remite el artículo 166 para regular la iniciativa de reforma constitucional?","options":["A los apartados 1 y 2 del artículo 87","Al artículo 92 exclusivamente","A los artículos 116 y 117","A los artículos 167 y 168"],"correct":0,"explanation":"El artículo 166 dispone que la iniciativa de reforma constitucional se ejercerá en los términos previstos en los apartados 1 y 2 del artículo 87.","reference":"Art. 166 CE","status":"revisada · contraste normativo BOE","source":"Temario AESPOL, Temas 1-2-3 (julio 2023) + contraste con legislación consolidada BOE"},{"id":"ce-073","topicId":"t1","topic":"Tema 1 · Constitución Española de 1978 y Título Preliminar","text":"¿Qué finalidad recoge el preámbulo respecto de la convivencia?","options":["Garantizar la convivencia democrática conforme a un orden económico y social justo","Establecer un Estado federal","Atribuir la soberanía a las Cortes","Regular la sucesión a la Corona"],"correct":0,"explanation":"El preámbulo proclama la voluntad de garantizar la convivencia democrática dentro de la Constitución y las leyes, conforme a un orden económico y social justo.","reference":"Preámbulo CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, actualizado julio 2023; contenido contrastado con el texto constitucional aplicable cuando procede"},{"id":"ce-074","topicId":"t1","topic":"Tema 1 · Constitución Española de 1978 y Título Preliminar","text":"Según el artículo 1.1, ¿cuáles son los valores superiores del ordenamiento jurídico?","options":["Libertad, justicia, igualdad y pluralismo político","Unidad, autonomía, solidaridad y legalidad","Libertad, seguridad, propiedad y trabajo","Justicia, legalidad, jerarquía y publicidad"],"correct":0,"explanation":"El artículo 1.1 enumera libertad, justicia, igualdad y pluralismo político.","reference":"Art. 1.1 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, actualizado julio 2023; contenido contrastado con el texto constitucional aplicable cuando procede"},{"id":"ce-075","topicId":"t1","topic":"Tema 1 · Constitución Española de 1978 y Título Preliminar","text":"¿Qué reconoce el artículo 2 junto a la unidad de la Nación española?","options":["El derecho a la autodeterminación","El derecho a la autonomía de nacionalidades y regiones y la solidaridad entre ellas","La soberanía de las comunidades autónomas","La independencia de las regiones"],"correct":1,"explanation":"El artículo 2 reconoce y garantiza el derecho a la autonomía y la solidaridad entre todas ellas.","reference":"Art. 2 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, actualizado julio 2023; contenido contrastado con el texto constitucional aplicable cuando procede"},{"id":"ce-076","topicId":"t1","topic":"Tema 1 · Constitución Española de 1978 y Título Preliminar","text":"¿Qué establece el artículo 3.2 sobre las demás lenguas españolas?","options":["Son oficiales en todo el Estado","Pueden ser oficiales en las respectivas comunidades autónomas conforme a sus estatutos","Son de conocimiento obligatorio en todo el Estado","No pueden utilizarse en documentos públicos"],"correct":1,"explanation":"Las demás lenguas españolas serán también oficiales en las respectivas comunidades autónomas de acuerdo con sus estatutos.","reference":"Art. 3.2 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, actualizado julio 2023; contenido contrastado con el texto constitucional aplicable cuando procede"},{"id":"ce-077","topicId":"t1","topic":"Tema 1 · Constitución Española de 1978 y Título Preliminar","text":"¿Dónde se utilizarán las banderas y enseñas propias de las comunidades autónomas junto a la de España?","options":["Solo en actos privados","En sus edificios públicos y actos oficiales","Solo en el Parlamento autonómico","Únicamente en días festivos"],"correct":1,"explanation":"El artículo 4.2 dispone su utilización junto a la bandera de España en edificios públicos y actos oficiales.","reference":"Art. 4.2 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, actualizado julio 2023; contenido contrastado con el texto constitucional aplicable cuando procede"},{"id":"ce-078","topicId":"t1","topic":"Tema 1 · Constitución Española de 1978 y Título Preliminar","text":"¿Cómo debe ser la estructura interna y el funcionamiento de los partidos políticos?","options":["Jerárquicos","Democráticos","Independientes del ordenamiento jurídico","Determinados por el Gobierno"],"correct":1,"explanation":"El artículo 6 exige que su estructura interna y funcionamiento sean democráticos.","reference":"Art. 6 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, actualizado julio 2023; contenido contrastado con el texto constitucional aplicable cuando procede"},{"id":"ce-079","topicId":"t1","topic":"Tema 1 · Constitución Española de 1978 y Título Preliminar","text":"¿Qué misión atribuye el artículo 8 a las Fuerzas Armadas?","options":["Dirigir la política exterior","Garantizar la soberanía e independencia, defender la integridad territorial y el ordenamiento constitucional","Aprobar las leyes orgánicas","Controlar la actividad judicial"],"correct":1,"explanation":"Es la misión recogida en el artículo 8.1.","reference":"Art. 8.1 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, actualizado julio 2023; contenido contrastado con el texto constitucional aplicable cuando procede"},{"id":"ce-080","topicId":"t1","topic":"Tema 1 · Constitución Española de 1978 y Título Preliminar","text":"¿Qué principio del artículo 9.3 exige que las normas sean publicadas para garantizar su conocimiento y eficacia?","options":["La publicidad de las normas","La autonomía territorial","La responsabilidad patrimonial","La libertad de empresa"],"correct":0,"explanation":"El artículo 9.3 garantiza la publicidad de las normas.","reference":"Art. 9.3 CE","status":"revisada · contraste normativo BOE","source":"Temario AESPOL, Temas 1-2-3 (julio 2023) + contraste con legislación consolidada BOE"},{"id":"ce-081","topicId":"t2","topic":"Tema 2 · Derechos y deberes fundamentales","text":"¿Qué artículo del Título I establece que la dignidad de la persona es fundamento del orden político y de la paz social?","options":["9","10","14","15"],"correct":1,"explanation":"El artículo 10.1 sitúa la dignidad de la persona y los derechos inviolables como fundamento del orden político y de la paz social.","reference":"Art. 10.1 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, actualizado julio 2023; contenido contrastado con el texto constitucional aplicable cuando procede"},{"id":"ce-082","topicId":"t2","topic":"Tema 2 · Derechos y deberes fundamentales","text":"¿Conforme a qué instrumentos deben interpretarse las normas sobre derechos fundamentales, según el artículo 10.2?","options":["Solo conforme a las leyes orgánicas","Conforme a la Declaración Universal de Derechos Humanos y a los tratados y acuerdos internacionales sobre las mismas materias ratificados por España","Conforme a los estatutos de autonomía","Conforme a la jurisprudencia del Tribunal Supremo exclusivamente"],"correct":1,"explanation":"El artículo 10.2 ordena interpretar las normas relativas a los derechos fundamentales y a las libertades reconocidas por la Constitución de conformidad con la Declaración Universal de Derechos Humanos y los tratados y acuerdos internacionales sobre las mismas materias ratificados por España.","reference":"Art. 10.2 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, actualizado julio 2023; contenido contrastado con el texto constitucional aplicable cuando procede"},{"id":"ce-083","topicId":"t2","topic":"Tema 2 · Derechos y deberes fundamentales","text":"¿Qué garantiza el artículo 11.2 respecto de los españoles de origen?","options":["Pueden ser privados de nacionalidad por ley","No pueden ser privados de su nacionalidad","No pueden adquirir otra nacionalidad","Su nacionalidad es temporal"],"correct":1,"explanation":"Ningún español de origen podrá ser privado de su nacionalidad.","reference":"Art. 11.2 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, actualizado julio 2023; contenido contrastado con el texto constitucional aplicable cuando procede"},{"id":"ce-084","topicId":"t2","topic":"Tema 2 · Derechos y deberes fundamentales","text":"¿A qué edad se alcanza la mayoría de edad según la Constitución?","options":["16 años","18 años","21 años","La que establezca cada comunidad autónoma"],"correct":1,"explanation":"El artículo 12 establece la mayoría de edad de los españoles a los 18 años.","reference":"Art. 12 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, actualizado julio 2023; contenido contrastado con el texto constitucional aplicable cuando procede"},{"id":"ce-085","topicId":"t2","topic":"Tema 2 · Derechos y deberes fundamentales","text":"¿Qué artículo reconoce a los extranjeros las libertades públicas del Título I en los términos establecidos por tratados y ley?","options":["11","12","13","14"],"correct":2,"explanation":"El artículo 13 regula los derechos de los extranjeros en España.","reference":"Art. 13 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, actualizado julio 2023; contenido contrastado con el texto constitucional aplicable cuando procede"},{"id":"ce-086","topicId":"t2","topic":"Tema 2 · Derechos y deberes fundamentales","text":"Según el artículo 17.3, ¿qué garantías asisten a toda persona detenida?","options":["Solo el derecho a guardar silencio","Información inmediata y comprensible de sus derechos y razones de la detención, no obligación de declarar y asistencia de abogado","Asistencia letrada únicamente después de comparecer ante el juez","Comunicación de la detención solo a la autoridad gubernativa"],"correct":1,"explanation":"El artículo 17.3 reconoce esas garantías durante la detención, en los términos que establezca la ley.","reference":"Art. 17.3 CE","status":"revisada · contraste normativo BOE","source":"Temario AESPOL, Temas 1-2-3 (julio 2023) + contraste con legislación consolidada BOE"},{"id":"ce-087","topicId":"t2","topic":"Tema 2 · Derechos y deberes fundamentales","text":"¿En cuál de estos supuestos puede entrar una autoridad en un domicilio sin consentimiento de su titular ni resolución judicial?","options":["Cuando exista una denuncia anónima","Cuando se trate de un delito leve","En caso de flagrante delito","Siempre que lo solicite un vecino"],"correct":2,"explanation":"El artículo 18.2 permite la entrada o registro sin consentimiento o resolución judicial en caso de flagrante delito.","reference":"Art. 18.2 CE","status":"revisada · contraste normativo BOE","source":"Temario AESPOL, Temas 1-2-3 (julio 2023) + contraste con legislación consolidada BOE"},{"id":"ce-088","topicId":"t2","topic":"Tema 2 · Derechos y deberes fundamentales","text":"¿Qué requisito constitucional permite intervenir las comunicaciones protegidas por el artículo 18.3?","options":["Una orden verbal de la autoridad gubernativa","Una resolución judicial, salvo lo que establezca la legislación excepcional constitucionalmente aplicable","Una autorización municipal","La mera apertura de diligencias policiales"],"correct":1,"explanation":"El secreto de las comunicaciones solo puede levantarse mediante resolución judicial, salvo las previsiones constitucionales específicas para estados excepcionales.","reference":"Art. 18.3 y 55 CE","status":"revisada · contraste normativo BOE","source":"Temario AESPOL, Temas 1-2-3 (julio 2023) + contraste con legislación consolidada BOE"},{"id":"ce-089","topicId":"t2","topic":"Tema 2 · Derechos y deberes fundamentales","text":"Según el artículo 19, ¿por qué motivos no puede limitarse la libertad de entrar y salir libremente de España?","options":["Por motivos económicos","Por motivos ideológicos o políticos","Por motivos de residencia en otra comunidad autónoma","Por no estar empadronado en el municipio de destino"],"correct":1,"explanation":"El artículo 19 establece expresamente que este derecho no podrá ser limitado por motivos políticos o ideológicos.","reference":"Art. 19 CE","status":"revisada · contraste normativo BOE","source":"Temario AESPOL, Temas 1-2-3 (julio 2023) + contraste con legislación consolidada BOE"},{"id":"ce-090","topicId":"t2","topic":"Tema 2 · Derechos y deberes fundamentales","text":"¿Qué exige el artículo 21.2 para las reuniones en lugares de tránsito público y manifestaciones?","options":["Autorización previa del alcalde","Autorización judicial previa","Comunicación previa a la autoridad, que solo podrá prohibirlas cuando existan razones fundadas de alteración del orden público con peligro para personas o bienes","Aprobación del Pleno municipal"],"correct":2,"explanation":"El artículo 21.2 exige comunicación previa, no autorización. La prohibición requiere razones fundadas de alteración del orden público con peligro para personas o bienes.","reference":"Art. 21.2 CE","status":"revisada · contraste normativo BOE","source":"Temario AESPOL, Temas 1-2-3 (julio 2023) + contraste con legislación consolidada BOE"},{"id":"ce-091","topicId":"t2","topic":"Tema 2 · Derechos y deberes fundamentales","text":"¿Qué exige el artículo 22 para la disolución o suspensión de una asociación?","options":["Acuerdo del Gobierno","Resolución judicial motivada","Autorización administrativa","Votación del Congreso"],"correct":1,"explanation":"Las asociaciones solo podrán ser disueltas o suspendidas en sus actividades en virtud de resolución judicial motivada.","reference":"Art. 22.4 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, actualizado julio 2023; contenido contrastado con el texto constitucional aplicable cuando procede"},{"id":"ce-092","topicId":"t2","topic":"Tema 2 · Derechos y deberes fundamentales","text":"¿Qué derecho reconoce el artículo 23.2?","options":["Acceder en condiciones de igualdad a funciones y cargos públicos","Obtener una vivienda digna","Negociación colectiva","Libertad de empresa"],"correct":0,"explanation":"El artículo 23.2 reconoce el acceso en condiciones de igualdad a funciones y cargos públicos, con los requisitos que señalen las leyes.","reference":"Art. 23.2 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, actualizado julio 2023; contenido contrastado con el texto constitucional aplicable cuando procede"},{"id":"ce-093","topicId":"t2","topic":"Tema 2 · Derechos y deberes fundamentales","text":"¿Qué derecho reconoce expresamente el artículo 24.2 en relación con la responsabilidad penal?","options":["La presunción de inocencia","La condena sin audiencia cuando exista flagrancia","La obligación de declarar contra uno mismo","La renuncia forzosa a la asistencia letrada"],"correct":0,"explanation":"El artículo 24.2 reconoce, entre otras garantías procesales, el derecho a la presunción de inocencia.","reference":"Art. 24.2 CE","status":"revisada · contraste normativo BOE","source":"Temario AESPOL, Temas 1-2-3 (julio 2023) + contraste con legislación consolidada BOE"},{"id":"ce-094","topicId":"t2","topic":"Tema 2 · Derechos y deberes fundamentales","text":"¿Qué prevé el artículo 30.2 respecto de las obligaciones militares?","options":["Que la objeción de conciencia está prohibida","Que la ley regulará las obligaciones militares, la objeción de conciencia y las demás causas de exención, pudiendo establecer una prestación social sustitutoria","Que el servicio militar es obligatorio sin excepciones","Que las comunidades autónomas regulan la defensa nacional"],"correct":1,"explanation":"El artículo 30.2 remite a la ley la regulación de las obligaciones militares, la objeción de conciencia y las causas de exención, pudiendo establecer una prestación social sustitutoria.","reference":"Art. 30.2 CE","status":"revisada · contraste normativo BOE","source":"Temario AESPOL, Temas 1-2-3 (julio 2023) + contraste con legislación consolidada BOE"},{"id":"ce-095","topicId":"t2","topic":"Tema 2 · Derechos y deberes fundamentales","text":"¿Qué reconoce el artículo 34.1 de la Constitución?","options":["El derecho de fundación para fines de interés general, con arreglo a la ley","El derecho a crear fundaciones para cualquier fin ilícito","La libertad sindical","El derecho de huelga"],"correct":0,"explanation":"El artículo 34.1 reconoce el derecho de fundación para fines de interés general con arreglo a la ley.","reference":"Art. 34.1 CE","status":"revisada · contraste normativo BOE","source":"Temario AESPOL, Temas 1-2-3 (julio 2023) + contraste con legislación consolidada BOE"},{"id":"ce-096","topicId":"t2","topic":"Tema 2 · Derechos y deberes fundamentales","text":"¿Qué contiene el artículo 35.1 de la Constitución?","options":["Solo el deber de trabajar","El deber de trabajar y el derecho al trabajo, a la libre elección de profesión u oficio, a la promoción y a una remuneración suficiente sin discriminación por razón de sexo","El derecho a una prestación económica incondicionada","La obligación de trabajar en el sector público"],"correct":1,"explanation":"El artículo 35.1 reconoce esos derechos y deberes laborales y prohíbe la discriminación por razón de sexo en la remuneración.","reference":"Art. 35.1 CE","status":"revisada · contraste normativo BOE","source":"Temario AESPOL, Temas 1-2-3 (julio 2023) + contraste con legislación consolidada BOE"},{"id":"ce-097","topicId":"t2","topic":"Tema 2 · Derechos y deberes fundamentales","text":"¿Cómo puede ejercerse el derecho de petición del artículo 29?","options":["Solo colectivamente","Individual y colectivamente, por escrito, en la forma y con los efectos que determine la ley","Solo por medios electrónicos","Únicamente ante el Congreso"],"correct":1,"explanation":"El artículo 29 reconoce el derecho de petición individual y colectiva por escrito.","reference":"Art. 29 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, actualizado julio 2023; contenido contrastado con el texto constitucional aplicable cuando procede"},{"id":"ce-098","topicId":"t2","topic":"Tema 2 · Derechos y deberes fundamentales","text":"Tras la reforma constitucional de 2024, ¿qué deben impulsar los poderes públicos conforme al artículo 49.2?","options":["La autonomía personal y la inclusión social de las personas con discapacidad en entornos universalmente accesibles","La sustitución de la protección legal por ayudas voluntarias","La atención exclusiva a personas mayores","La creación de un sistema educativo separado"],"correct":0,"explanation":"El artículo 49.2, reformado en 2024, ordena impulsar políticas que garanticen la plena autonomía personal y la inclusión social de las personas con discapacidad en entornos universalmente accesibles.","reference":"Art. 49.2 CE; reforma publicada en BOE el 17/02/2024","status":"revisada · contraste normativo BOE","source":"Temario AESPOL + reforma del artículo 49 publicada en BOE el 17/02/2024"},{"id":"ce-099","topicId":"t2","topic":"Tema 2 · Derechos y deberes fundamentales","text":"¿Qué establece el artículo 32.1 sobre el matrimonio?","options":["Solo puede contraerse entre españoles","El hombre y la mujer tienen derecho a contraer matrimonio con plena igualdad jurídica","Requiere autorización judicial","Su regulación corresponde exclusivamente a las comunidades autónomas"],"correct":1,"explanation":"El artículo 32.1 reconoce el derecho a contraer matrimonio con plena igualdad jurídica.","reference":"Art. 32.1 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, actualizado julio 2023; contenido contrastado con el texto constitucional aplicable cuando procede"},{"id":"ce-100","topicId":"t2","topic":"Tema 2 · Derechos y deberes fundamentales","text":"¿Qué reconoce el artículo 38?","options":["La libertad de empresa en el marco de la economía de mercado","El derecho a la huelga","La propiedad comunal","La libertad sindical"],"correct":0,"explanation":"El artículo 38 reconoce la libertad de empresa en el marco de la economía de mercado.","reference":"Art. 38 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, actualizado julio 2023; contenido contrastado con el texto constitucional aplicable cuando procede"},{"id":"ce-101","topicId":"t3","topic":"Tema 3 · Garantías y suspensión de derechos","text":"¿Qué reserva establece el artículo 53.1 para la regulación del ejercicio de los derechos y libertades del Capítulo II?","options":["Pueden regularse libremente por reglamento","Solo pueden regularse por ley, que debe respetar en todo caso su contenido esencial","Deben regularse siempre mediante ley orgánica","Su regulación corresponde exclusivamente al Tribunal Constitucional"],"correct":1,"explanation":"El artículo 53.1 establece reserva de ley y exige respetar el contenido esencial de los derechos y libertades.","reference":"Art. 53.1 CE","status":"revisada · contraste normativo BOE","source":"Temario AESPOL, Temas 1-2-3 (julio 2023) + contraste con legislación consolidada BOE"},{"id":"ce-102","topicId":"t3","topic":"Tema 3 · Garantías y suspensión de derechos","text":"¿Qué garantía específica exige el artículo 53.3 para que los principios rectores puedan alegarse ante la jurisdicción ordinaria?","options":["Que exista una ley que los desarrolle","Que lo autorice previamente el Defensor del Pueblo","Que se interponga siempre recurso de amparo","Que se apruebe una ley orgánica estatal para cada principio"],"correct":0,"explanation":"Los principios rectores solo pueden alegarse ante la jurisdicción ordinaria de acuerdo con lo que dispongan las leyes que los desarrollen.","reference":"Art. 53.3 CE","status":"revisada · contraste normativo BOE","source":"Temario AESPOL, Temas 1-2-3 (julio 2023) + contraste con legislación consolidada BOE"},{"id":"ce-103","topicId":"t3","topic":"Tema 3 · Garantías y suspensión de derechos","text":"Una vez obtenida la autorización del Congreso para declarar el estado de excepción, ¿cómo lo declara el Gobierno?","options":["Mediante decreto acordado en Consejo de Ministros","Mediante ley orgánica aprobada por el Senado","Mediante orden del ministro del Interior","Mediante real decreto del Rey sin acuerdo del Consejo de Ministros"],"correct":0,"explanation":"El artículo 14 de la LO 4/1981 dispone que, obtenida la autorización del Congreso, el Gobierno declara el estado de excepción mediante decreto acordado en Consejo de Ministros.","reference":"Art. 14 LO 4/1981","status":"revisada · contraste normativo BOE","source":"Temario AESPOL, Temas 1-2-3 (julio 2023) + contraste con legislación consolidada BOE"},{"id":"ce-104","topicId":"t3","topic":"Tema 3 · Garantías y suspensión de derechos","text":"¿Qué grupo de derechos puede incluirse en la suspensión prevista por el artículo 55.1?","options":["Cualquier derecho reconocido en el Título I","Los derechos enumerados en el artículo 55.1, entre ellos los de los artículos 17, 18.2 y 18.3, 19, 20.1 a) y d), 20.5, 21, 28.2 y 37.2, con la excepción constitucional del art. 17.3 en estado de excepción","Únicamente el derecho de reunión","Solo los derechos de propiedad y herencia"],"correct":1,"explanation":"El artículo 55.1 contiene una lista tasada de derechos susceptibles de suspensión en los estados de excepción o de sitio y establece una excepción específica respecto del artículo 17.3 durante el estado de excepción.","reference":"Art. 55.1 CE","status":"revisada · contraste normativo BOE","source":"Temario AESPOL, Temas 1-2-3 (julio 2023) + contraste con legislación consolidada BOE"},{"id":"ce-105","topicId":"t3","topic":"Tema 3 · Garantías y suspensión de derechos","text":"¿Qué duración máxima establece la Constitución para la prórroga del estado de excepción?","options":["No puede prorrogarse","Puede prorrogarse por otro plazo igual, con los mismos requisitos","Puede prorrogarse indefinidamente por el Gobierno","Puede prorrogarse por 15 días sin autorización"],"correct":1,"explanation":"El artículo 116.3 permite prorrogar el estado de excepción por otro plazo igual, con los mismos requisitos.","reference":"Art. 116.3 CE","status":"revisada · contraste normativo BOE","source":"Temario AESPOL, Temas 1-2-3 (julio 2023) + contraste con legislación consolidada BOE"},{"id":"ce-106","topicId":"t3","topic":"Tema 3 · Garantías y suspensión de derechos","text":"¿Qué debe determinar el decreto de declaración del estado de alarma?","options":["Solo el nombre de la autoridad competente","El ámbito territorial, la duración y los efectos del estado","La suspensión general de los derechos fundamentales","La composición de la Diputación Permanente"],"correct":1,"explanation":"El artículo 116.2 exige que el decreto determine el ámbito territorial, la duración y los efectos del estado de alarma.","reference":"Art. 116.2 CE; LO 4/1981","status":"revisada · contraste normativo BOE","source":"Temario AESPOL, Temas 1-2-3 (julio 2023) + contraste con legislación consolidada BOE"},{"id":"ce-107","topicId":"t3","topic":"Tema 3 · Garantías y suspensión de derechos","text":"¿Quién dirige la autoridad durante el estado de alarma, con carácter general, según la Ley Orgánica 4/1981?","options":["El presidente del Congreso","El Gobierno o, por delegación, el presidente de la comunidad autónoma cuando la declaración afecte exclusivamente a todo o parte de su territorio","El alcalde del municipio afectado","El Tribunal Constitucional"],"correct":1,"explanation":"El artículo 7 de la LO 4/1981 atribuye la autoridad competente al Gobierno o, por delegación, al presidente de la comunidad autónoma en el supuesto territorial previsto.","reference":"Art. 7 LO 4/1981","status":"revisada · contraste normativo BOE","source":"Temario AESPOL, Temas 1-2-3 (julio 2023) + contraste con legislación consolidada BOE"},{"id":"ce-108","topicId":"t3","topic":"Tema 3 · Garantías y suspensión de derechos","text":"¿Qué sucede con el funcionamiento de los poderes constitucionales del Estado durante los estados de alarma, excepción y sitio?","options":["Queda interrumpido","Se suspende el funcionamiento del Congreso y del Senado","No se interrumpe el normal funcionamiento de los poderes constitucionales","Pasa íntegramente al Gobierno"],"correct":2,"explanation":"El artículo 116.5 CE y el artículo 1.4 LO 4/1981 establecen la continuidad del funcionamiento de los poderes constitucionales, con las previsiones específicas sobre el Congreso.","reference":"Art. 116.5 CE; art. 1.4 LO 4/1981","status":"revisada · contraste normativo BOE","source":"Temario AESPOL, Temas 1-2-3 (julio 2023) + contraste con legislación consolidada BOE"},{"id":"ce-109","topicId":"t3","topic":"Tema 3 · Garantías y suspensión de derechos","text":"¿Qué estados excepcionales contempla el artículo 116 de la Constitución?","options":["Alarma, excepción y sitio","Alarma, emergencia y guerra","Excepción, sitio y emergencia","Alarma, sitio y conmoción"],"correct":0,"explanation":"El artículo 116 contempla los estados de alarma, excepción y sitio.","reference":"Art. 116 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, actualizado julio 2023; contenido contrastado con el texto constitucional aplicable cuando procede"},{"id":"ce-110","topicId":"t3","topic":"Tema 3 · Garantías y suspensión de derechos","text":"¿Qué norma orgánica regula los estados de alarma, excepción y sitio?","options":["LO 2/1979","LO 3/1981","LO 4/1981","LO 6/1985"],"correct":2,"explanation":"La Ley Orgánica 4/1981 regula los estados de alarma, excepción y sitio.","reference":"LO 4/1981","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, actualizado julio 2023; contenido contrastado con el texto constitucional aplicable cuando procede"},{"id":"ce-111","topicId":"t3","topic":"Tema 3 · Garantías y suspensión de derechos","text":"Durante el estado de alarma, ¿qué obligación tiene el Gobierno respecto del Congreso de los Diputados?","options":["Pedir autorización previa para declarar el estado","Dar cuenta de la declaración y suministrar la información que le sea requerida","Solicitar la disolución del Congreso","Remitir la declaración al Senado para su ratificación"],"correct":1,"explanation":"El artículo 8.1 de la LO 4/1981 obliga al Gobierno a dar cuenta al Congreso de la declaración y suministrarle la información que le sea requerida.","reference":"Art. 8.1 LO 4/1981","status":"revisada · contraste normativo BOE","source":"Temario AESPOL, Temas 1-2-3 (julio 2023) + contraste con legislación consolidada BOE"},{"id":"ce-112","topicId":"t3","topic":"Tema 3 · Garantías y suspensión de derechos","text":"Durante el estado de alarma, ¿qué sucede con los cuerpos de Policía de las comunidades autónomas y de las corporaciones locales del territorio afectado?","options":["Quedan automáticamente disueltos","Quedan bajo las órdenes directas de la autoridad competente en lo necesario para proteger personas, bienes y lugares","Pasan a depender orgánicamente del Congreso","Solo pueden actuar con autorización judicial individual"],"correct":1,"explanation":"El artículo 9.1 de la LO 4/1981 sitúa a esos cuerpos policiales bajo las órdenes directas de la autoridad competente en cuanto sea necesario para la protección de personas, bienes y lugares.","reference":"Art. 9.1 LO 4/1981","status":"revisada · contraste normativo BOE","source":"Temario AESPOL, Temas 1-2-3 (julio 2023) + contraste con legislación consolidada BOE"},{"id":"ce-113","topicId":"t3","topic":"Tema 3 · Garantías y suspensión de derechos","text":"¿Quién autoriza la prórroga del estado de alarma?","options":["El Senado","El Congreso de los Diputados","El Tribunal Supremo","El Consejo de Estado"],"correct":1,"explanation":"La prórroga del estado de alarma requiere autorización del Congreso de los Diputados.","reference":"Art. 116.2 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, actualizado julio 2023; contenido contrastado con el texto constitucional aplicable cuando procede"},{"id":"ce-114","topicId":"t3","topic":"Tema 3 · Garantías y suspensión de derechos","text":"¿Quién solicita al Congreso la autorización para declarar el estado de excepción?","options":["El Rey","El Gobierno","El Presidente del Congreso","El Tribunal Constitucional"],"correct":1,"explanation":"El Gobierno debe solicitar autorización previa al Congreso para declarar el estado de excepción.","reference":"Art. 116.3 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, actualizado julio 2023; contenido contrastado con el texto constitucional aplicable cuando procede"},{"id":"ce-115","topicId":"t3","topic":"Tema 3 · Garantías y suspensión de derechos","text":"¿Cuál es la duración máxima inicial del estado de excepción?","options":["15 días","30 días","45 días","60 días"],"correct":1,"explanation":"La duración del estado de excepción no puede exceder de 30 días, prorrogables por otro plazo igual con los mismos requisitos.","reference":"Art. 116.3 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, actualizado julio 2023; contenido contrastado con el texto constitucional aplicable cuando procede"},{"id":"ce-116","topicId":"t3","topic":"Tema 3 · Garantías y suspensión de derechos","text":"¿Qué órgano determina la duración del estado de sitio?","options":["El Gobierno mediante real decreto","El Congreso de los Diputados en la declaración","El Senado por mayoría absoluta","El Rey mediante decreto"],"correct":1,"explanation":"El artículo 116.4 establece que el Congreso determina el ámbito territorial, la duración y las condiciones del estado de sitio.","reference":"Art. 116.4 CE","status":"revisada · contraste normativo BOE","source":"Temario AESPOL, Temas 1-2-3 (julio 2023) + contraste con legislación consolidada BOE"},{"id":"ce-117","topicId":"t3","topic":"Tema 3 · Garantías y suspensión de derechos","text":"¿Qué duración máxima establece expresamente la Constitución para el estado de sitio?","options":["15 días","30 días","No establece un límite temporal expreso","60 días"],"correct":2,"explanation":"El artículo 116.4 no fija una duración máxima; el Congreso determina su duración en la declaración.","reference":"Art. 116.4 CE","status":"revisada · contraste normativo BOE","source":"AESPOL, Temas 1-2-3, actualizado julio 2023; contenido contrastado con el texto constitucional aplicable cuando procede"},{"id":"ce-118","topicId":"t3","topic":"Tema 3 · Garantías y suspensión de derechos","text":"¿Qué obligación adicional establece el artículo 8.2 de la Ley Orgánica 4/1981 para el Gobierno durante el estado de alarma?","options":["Dar cuenta al Congreso de los decretos que dicte durante su vigencia en relación con el estado de alarma","Solicitar autorización del Senado para cada medida","Comunicar cada decreto exclusivamente a los alcaldes","Remitir los decretos al Tribunal Constitucional antes de publicarlos"],"correct":0,"explanation":"El artículo 8.2 obliga al Gobierno a dar cuenta al Congreso de los decretos que dicte durante la vigencia del estado de alarma en relación con este.","reference":"Art. 8.2 LO 4/1981","status":"revisada · contraste normativo BOE","source":"Temario AESPOL, Temas 1-2-3 (julio 2023) + contraste con legislación consolidada BOE"},{"id":"ce-119","topicId":"t3","topic":"Tema 3 · Garantías y suspensión de derechos","text":"¿Qué requisito de control parlamentario acompaña a la suspensión individual de derechos del artículo 55.2?","options":["No existe control parlamentario","Debe existir adecuado control parlamentario, además de necesaria intervención judicial y regulación por ley orgánica","Basta con una comunicación al ayuntamiento","La autorización corresponde exclusivamente al Senado"],"correct":1,"explanation":"El artículo 55.2 exige ley orgánica, necesaria intervención judicial y adecuado control parlamentario.","reference":"Art. 55.2 CE","status":"revisada · contraste normativo BOE","source":"Temario AESPOL, Temas 1-2-3 (julio 2023) + contraste con legislación consolidada BOE"},{"id":"ce-120","topicId":"t3","topic":"Tema 3 · Garantías y suspensión de derechos","text":"¿Qué puede autorizar la declaración del estado de sitio respecto de las garantías del detenido reconocidas en el artículo 17.3 CE?","options":["Su suspensión temporal","Su supresión definitiva para todos los detenidos","Su sustitución por una autorización municipal","Nada: nunca pueden suspenderse en ningún estado"],"correct":0,"explanation":"El artículo 32.3 de la LO 4/1981 permite que la declaración del estado de sitio autorice la suspensión temporal de las garantías jurídicas del detenido reconocidas en el artículo 17.3 CE.","reference":"Art. 32.3 LO 4/1981; art. 17.3 CE","status":"revisada · contraste normativo BOE","source":"Temario AESPOL, Temas 1-2-3 (julio 2023) + contraste con legislación consolidada BOE"}];
let data=load();
(function mergeInitialQuestions(){const userQuestions=(data.questions||[]).filter(q=>!/^ce-\d{3}$/.test(q.id||''));data.questions=[...OPOPL_INITIAL_QUESTIONS,...userQuestions];localStorage.setItem(KEY,JSON.stringify(data));})();
let timer={running:false,mode:'study',started:0,elapsed:0,interval:null};
function load(){try{let d=JSON.parse(localStorage.getItem(KEY))||{};return {...{topics:seed,done:{},doubts:[],sessions:[],articles:[],questions:[],reviews:[],testResults:[]},...d}}catch(e){return{topics:seed,done:{},doubts:[],sessions:[],articles:[],questions:[],reviews:[],testResults:[]}}}
function persist(){localStorage.setItem(KEY,JSON.stringify(data));renderAll()}
function toast(s){let t=document.getElementById('toast');t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2200)}
function go(page){document.querySelectorAll('.page').forEach(x=>x.classList.remove('active'));document.getElementById('page-'+page).classList.add('active');document.querySelectorAll('.nav button').forEach(x=>x.classList.toggle('active',x.dataset.page===page));let names={inicio:'Panel de preparación',temario:'Mi temario',sesion:'Sesión de estudio',dudas:'Mis dudas',registro:'Registro de estudio',repaso:'Repaso diario',tests:'Tests por tema'};document.getElementById('pageTitle').textContent=names[page];if(page==='sesion'){fillTopicSelects()}if(page==='repaso'){renderReviewPage()}if(page==='tests'){fillQuestionSelects();renderQuestionBank()} }
document.querySelectorAll('.nav button').forEach(b=>b.addEventListener('click',()=>go(b.dataset.page)));
function counts(){let eps=data.topics.flatMap(t=>t.epigraphs||[]),done=eps.filter(e=>data.done[e.id]).length,topicsDone=data.topics.filter(t=>(t.epigraphs||[]).length&&(t.epigraphs||[]).every(e=>data.done[e.id])).length;return{eps,done,topicsDone,pct:eps.length?Math.round(done/eps.length*100):0}}
function renderAll(){renderStats();renderTopics();renderDoubts();renderLogs();if(document.getElementById('qTopic'))fillQuestionSelects();}
function renderStats(){let c=counts(),mins=data.sessions.reduce((s,x)=>s+(x.mode==='study'?x.seconds:0),0);document.getElementById('statTopics').textContent=`${c.topicsDone}/${data.topics.length}`;document.getElementById('statEpis').textContent=c.pct+'%';document.getElementById('statTime').textContent=Math.floor(mins/60)+' h '+Math.floor(mins%3600/60)+' min';document.getElementById('statDoubts').textContent=data.doubts.filter(d=>!d.resolved).length;document.getElementById('homeTopics').innerHTML=data.topics.map(t=>{let n=t.epigraphs.length,d=t.epigraphs.filter(e=>data.done[e.id]).length;return `<div class="topic"><div class="topic-top"><strong>${esc(t.name)}</strong><small>${d}/${n}</small></div><div class="progress" style="margin-top:10px"><i style="width:${n?d/n*100:0}%"></i></div></div>`}).join('')||'<div class="empty">Añade tu primer tema para empezar.</div>';let recent=[...data.sessions.map(s=>({date:s.date,label:s.label,detail:format(s.seconds)+' · '+(s.mode==='study'?'Estudio':'Descanso')})),...data.articles.map(a=>({date:a.date,label:'Artículos: '+a.numbers,detail:a.topic}))].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5);document.getElementById('recentActivity').innerHTML=recent.length?recent.map(x=>`<div class="list-item"><div class="body"><strong>${esc(x.label)}</strong><p>${esc(x.detail)} · ${new Date(x.date).toLocaleDateString('es-ES')}</p></div></div>`).join(''):'<div class="empty">Todavía no hay actividad registrada.</div>'}
function renderTopics(){let html=data.topics.map(t=>{let n=t.epigraphs.length,d=t.epigraphs.filter(e=>data.done[e.id]).length,all=n&&d===n;return `<div class="topic"><div class="topic-top"><input class="check" type="checkbox" ${all?'checked':''} aria-label="Tema terminado" onchange="toggleTopic('${t.id}',this.checked)"><strong>${esc(t.name)}</strong><small>${d}/${n} epígrafes</small><button class="button ghost" onclick="renameTopic('${t.id}')">Editar</button><button class="button ghost" onclick="addEpigraph('${t.id}')">＋ Epígrafe</button></div><div class="progress" style="margin:10px 0 0 29px"><i style="width:${n?d/n*100:0}%"></i></div><div class="epigraphs">${t.epigraphs.map(e=>`<label class="epigraph"><input class="check" type="checkbox" ${data.done[e.id]?'checked':''} onchange="toggleEpi('${e.id}',this.checked)"><span>${esc(e.name)}</span><button class="button ghost" onclick="renameEpi('${t.id}','${e.id}')" type="button">Editar</button></label>`).join('')}</div></div>`}).join('');document.getElementById('topicList').innerHTML=html||'<div class="empty">Aún no hay temas. Añade uno para comenzar.</div>';document.getElementById('topicSummary').textContent=`${data.topics.length} temas · ${counts().eps.length} epígrafes`}
function toggleEpi(id,v){data.done[id]=v;persist()}function toggleTopic(id,v){let t=data.topics.find(x=>x.id===id);t.epigraphs.forEach(e=>data.done[e.id]=v);persist()}
function addTopic(){let name=prompt('Nombre del nuevo tema:');if(!name?.trim())return;data.topics.push({id:uid(),name:name.trim(),epigraphs:[]});persist();toast('Tema añadido')}
function renameTopic(id){let t=data.topics.find(x=>x.id===id),name=prompt('Editar nombre del tema:',t.name);if(name?.trim()){t.name=name.trim();persist()}}
function addEpigraph(id){let t=data.topics.find(x=>x.id===id),name=prompt('Nombre del nuevo epígrafe:');if(!name?.trim())return;t.epigraphs.push({id:uid(),name:name.trim()});persist();toast('Epígrafe añadido')}
function renameEpi(tid,eid){let e=data.topics.find(t=>t.id===tid).epigraphs.find(x=>x.id===eid),name=prompt('Editar epígrafe:',e.name);if(name?.trim()){e.name=name.trim();persist()}}
function fillTopicSelects(){let opts=data.topics.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('');['timerTopic','articlesTopic','doubtTopic'].forEach(id=>document.getElementById(id).innerHTML=opts||'<option value="">Añade un tema primero</option>');fillEpigraphSelect();fillDoubtEpis()}
function fillEpigraphSelect(){let id=document.getElementById('timerTopic').value,t=data.topics.find(x=>x.id===id);document.getElementById('timerEpi').innerHTML=(t?.epigraphs||[]).map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('')||'<option value="">Sin epígrafes</option>'}
function fillDoubtEpis(){let id=document.getElementById('doubtTopic').value,t=data.topics.find(x=>x.id===id);document.getElementById('doubtEpi').innerHTML=(t?.epigraphs||[]).map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('')||'<option value="">Sin epígrafes</option>'}
function setMode(mode){if(timer.running)finishTimer();timer.mode=mode;document.getElementById('timerMode').textContent=mode==='study'?'Estudio':'Descanso';document.getElementById('clockLabel').textContent=mode==='study'?'Tiempo de concentración':'Tiempo de descanso'}
function startTimer(){if(timer.running)return;timer.running=true;timer.started=Date.now();document.getElementById('startBtn').textContent='En marcha';timer.interval=setInterval(updateClock,500);updateClock()}
function pauseTimer(){if(!timer.running)return;timer.elapsed+=Math.floor((Date.now()-timer.started)/1000);timer.running=false;clearInterval(timer.interval);document.getElementById('startBtn').textContent='Reanudar';updateClock()}
function updateClock(){let s=timer.elapsed+(timer.running?Math.floor((Date.now()-timer.started)/1000):0);document.getElementById('clock').textContent=format(s)}
function finishTimer(){if(timer.running){timer.elapsed+=Math.floor((Date.now()-timer.started)/1000);timer.running=false;clearInterval(timer.interval)}if(timer.elapsed>0){let tid=document.getElementById('timerTopic').value,eid=document.getElementById('timerEpi').value,t=data.topics.find(x=>x.id===tid),e=t?.epigraphs.find(x=>x.id===eid);data.sessions.unshift({date:new Date().toISOString(),mode:timer.mode,seconds:timer.elapsed,label:e?e.name:(t?.name||'Sesión general'),topic:t?.name||'Sin tema'});persist();toast('Sesión guardada')}timer.elapsed=0;document.getElementById('startBtn').textContent='Empezar';updateClock()}
function saveArticles(){let topic=data.topics.find(t=>t.id===document.getElementById('articlesTopic').value),numbers=document.getElementById('articles').value.split(/[;,\s]+/).filter(Boolean);if(!numbers.length){toast('Introduce al menos un número de artículo');return}data.articles.unshift({date:new Date().toISOString(),topic:topic?.name||'Sin tema',numbers:numbers.join(', '),note:document.getElementById('sessionNote').value.trim()});document.getElementById('articles').value='';document.getElementById('sessionNote').value='';persist();toast('Artículos registrados')}
function addDoubt(){let tid=document.getElementById('doubtTopic').value,t=data.topics.find(x=>x.id===tid),eid=document.getElementById('doubtEpi').value,e=t?.epigraphs.find(x=>x.id===eid),text=document.getElementById('doubtText').value.trim();if(!text){toast('Describe brevemente la duda');return}data.doubts.unshift({id:uid(),date:new Date().toISOString(),topic:t?.name||'Sin tema',epigraph:e?.name||'Sin epígrafe',status:document.getElementById('doubtStatus').value,law:document.getElementById('doubtLaw').value.trim(),text,resolved:false});document.getElementById('doubtText').value='';document.getElementById('doubtLaw').value='';persist();toast('Duda guardada')}
function renderDoubts(){let arr=data.doubts.filter(d=>!d.resolved);document.getElementById('doubtList').innerHTML=arr.length?arr.map(d=>`<div class="list-item"><div class="body"><span class="pill ${d.status==='No comprendido'?'red':d.status==='Necesito reforzar'?'amber':''}">${esc(d.status)}</span><p><strong>${esc(d.topic)} · ${esc(d.epigraph)}</strong></p><p>${esc(d.text)}</p>${d.law?`<p>${esc(d.law)}</p>`:''}<p>${new Date(d.date).toLocaleDateString('es-ES')}</p><button class="button ghost" onclick="resolveDoubt('${d.id}')">Marcar resuelta</button></div></div>`).join(''):'<div class="empty">No tienes dudas pendientes.</div>'}
function resolveDoubt(id){let d=data.doubts.find(x=>x.id===id);d.resolved=true;d.resolvedAt=new Date().toISOString();persist();toast('Duda marcada como resuelta')}
function renderLogs(){document.getElementById('articleLog').innerHTML=data.articles.length?data.articles.map(a=>`<div class="list-item"><div class="body"><strong>${esc(a.topic)}</strong><p>${esc(a.numbers.split(',').map(n=>'Art. '+n).join(' · '))}</p><p>${new Date(a.date).toLocaleDateString('es-ES')}${a.note?' · '+esc(a.note):''}</p></div></div>`).join(''):'<div class="empty">Aún no has registrado artículos.</div>';document.getElementById('sessionLog').innerHTML=data.sessions.length?data.sessions.map(s=>`<div class="list-item"><div class="body"><strong>${esc(s.label)}</strong><p>${s.mode==='study'?'Estudio':'Descanso'} · ${format(s.seconds)}</p><p>${new Date(s.date).toLocaleDateString('es-ES')}</p></div></div>`).join(''):'<div class="empty">Aún no hay sesiones registradas.</div>'}
let activeQuiz=null;
function fillQuestionSelects(){let opts=data.topics.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('');['qTopic','testTopic'].forEach(id=>{let el=document.getElementById(id);if(el)el.innerHTML=opts||'<option value="">Añade un tema</option>'});renderBankSummary()}
function saveQuestion(){let topicId=document.getElementById('qTopic').value,topic=data.topics.find(t=>t.id===topicId),text=document.getElementById('qText').value.trim(),options=['qA','qB','qC','qD'].map(id=>document.getElementById(id).value.trim()),explanation=document.getElementById('qExplain').value.trim(),correct=Number(document.getElementById('qCorrect').value);if(!topic||!text||options.some(x=>!x)){toast('Completa el tema, el enunciado y las cuatro opciones');return}data.questions.unshift({id:uid(),topicId,topic:topic.name,text,options,correct,explanation,createdAt:new Date().toISOString()});['qText','qA','qB','qC','qD','qExplain'].forEach(id=>document.getElementById(id).value='');persist();fillQuestionSelects();renderQuestionBank();toast('Pregunta guardada')}
function renderBankSummary(){let id=document.getElementById('testTopic')?.value||data.topics[0]?.id, n=data.questions.filter(q=>q.topicId===id).length;let el=document.getElementById('bankSummary');if(el)el.textContent=`${n} preguntas disponibles para este tema. Se necesitan al menos 40 para generar un simulacro completo.`}
function renderQuestionBank(){let el=document.getElementById('questionBank');if(!el)return;el.innerHTML=data.questions.length?data.questions.map(q=>`<div class="list-item"><div class="body"><strong>${esc(q.topic)}</strong><p>${esc(q.text)}</p><p class="question-meta">${q.options.length} opciones · Respuesta ${'ABCD'[q.correct]} · ${esc(q.status||'Pregunta personal, sin estado de verificación')}</p><p class="question-meta">${esc(q.reference||q.source||'Sin referencia jurídica registrada')}</p><button class="button ghost" onclick="deleteQuestion('${q.id}')">Eliminar</button></div></div>`).join(''):'<div class="empty">Todavía no has añadido preguntas. No se incluyen preguntas jurídicas de ejemplo para evitar entrenarte con contenido no verificado.</div>';renderBankSummary()}
function deleteQuestion(id){if(!confirm('¿Eliminar esta pregunta del banco?'))return;data.questions=data.questions.filter(q=>q.id!==id);persist();renderQuestionBank();toast('Pregunta eliminada')}
function startTest(){let id=document.getElementById('testTopic').value,bank=data.questions.filter(q=>q.topicId===id);if(bank.length<40){toast(`Faltan ${40-bank.length} preguntas para un simulacro completo`);return}activeQuiz={kind:'test',topicId:id,questions:shuffle(bank).slice(0,40),index:0,answers:[],submitted:false};renderActiveQuiz('testArea')}
function startDailyReview(){let last=data.sessions.find(s=>s.mode==='study'&&s.topic),topic=data.topics.find(t=>t.name===last?.topic),pool=topic?data.questions.filter(q=>q.topicId===topic.id):[];if(pool.length<3){document.getElementById('dailyQuiz').innerHTML='<div class="empty">No hay tres preguntas disponibles del último tema estudiado. Añade al menos tres preguntas verificadas de ese tema en Tests.</div>';return}let today=new Date().toISOString().slice(0,10),existing=data.reviews.find(r=>r.date.slice(0,10)===today);let qs=existing?existing.questionIds.map(id=>data.questions.find(q=>q.id===id)).filter(Boolean):shuffle(pool).slice(0,3);if(!existing){data.reviews.unshift({id:uid(),date:new Date().toISOString(),topicId:topic.id,topic:topic.name,questionIds:qs.map(q=>q.id),answers:[],completed:false});persist()}activeQuiz={kind:'review',topicId:topic.id,questions:qs,index:0,answers:[],submitted:false};renderActiveQuiz('dailyQuiz')}
function shuffle(arr){let a=[...arr];for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function renderActiveQuiz(target){let el=document.getElementById(target);if(!activeQuiz){el.innerHTML='';return}let q=activeQuiz.questions[activeQuiz.index];if(!q){finishQuiz(target);return}let letters=['A','B','C','D'];el.innerHTML=`<div class="question"><div class="question-meta">${esc(q.topic)} · Pregunta ${activeQuiz.index+1} de ${activeQuiz.questions.length}</div><h3>${esc(q.text)}</h3>${q.options.map((o,i)=>`<label class="option"><input type="radio" name="answer-${activeQuiz.index}" value="${i}" ${activeQuiz.answers[activeQuiz.index]===i?'checked':''}><span><strong>${letters[i]}.</strong> ${esc(o)}</span></label>`).join('')}<div class="quiz-actions"><button class="button" onclick="answerAndNext('${target}')">${activeQuiz.index===activeQuiz.questions.length-1?'Finalizar':'Siguiente'}</button></div></div>`}
function answerAndNext(target){let chosen=document.querySelector(`input[name="answer-${activeQuiz.index}"]:checked`);if(!chosen){toast('Selecciona una respuesta');return}activeQuiz.answers[activeQuiz.index]=Number(chosen.value);activeQuiz.index++;renderActiveQuiz(target)}
function finishQuiz(target){let total=activeQuiz.questions.length,correct=activeQuiz.questions.reduce((n,q,i)=>n+(activeQuiz.answers[i]===q.correct?1:0),0),kind=activeQuiz.kind;let detail=activeQuiz.questions.map((q,i)=>({question:q.text,selected:activeQuiz.answers[i],correct:q.correct,explanation:q.explanation}));if(kind==='test'){data.testResults.unshift({date:new Date().toISOString(),topic:activeQuiz.questions[0]?.topic||'',correct,total,detail})}else{let r=data.reviews.find(x=>x.questionIds.join('|')===activeQuiz.questions.map(q=>q.id).join('|')&&!x.completed);if(r){r.completed=true;r.answers=activeQuiz.answers;r.correct=correct;r.total=total;r.completedAt=new Date().toISOString()}}persist();document.getElementById(target).innerHTML=`<div class="feedback ${correct===total?'good':'bad'}"><strong>Resultado: ${correct}/${total} aciertos (${Math.round(correct/total*100)}%)</strong><p>${kind==='review'?'Repaso diario completado.':'Simulacro completado.'}</p></div>${detail.map((d,i)=>`<div class="question"><strong>${i+1}. ${esc(d.question)}</strong><p>Tu respuesta: ${d.selected==null?'Sin responder':'ABCD'[d.selected]} · Correcta: ${'ABCD'[d.correct]}</p><p>${d.selected===d.correct?'Correcto.':'Incorrecto.'} ${esc(d.explanation||'Sin explicación añadida.')}</p></div>`).join('')}`;activeQuiz=null;renderReviewPage();renderQuestionBank()}
function renderReviewPage(){let info=document.getElementById('dailyInfo');if(info){let last=data.sessions.find(s=>s.mode==='study'&&s.topic);info.textContent=last?`Último tema registrado: ${last.topic}. El repaso seleccionará tres preguntas de ese tema.`:'Todavía no hay una sesión de estudio registrada. Registra una sesión para determinar el tema anterior.'}let hist=document.getElementById('reviewHistory');if(hist)hist.innerHTML=data.reviews.length?data.reviews.slice(0,10).map(r=>`<div class="list-item"><div class="body"><strong>${esc(r.topic)}</strong><p>${new Date(r.date).toLocaleDateString('es-ES')} · ${r.completed?`${r.correct}/${r.total} aciertos`:'Pendiente'}</p></div></div>`).join(''):'<div class="empty">Todavía no hay repasos realizados.</div>'}
function exportBackup(){
 const payload={app:'OpoPL',schema:1,exportedAt:new Date().toISOString(),data};
 const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});
 const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='OpoPL-copia-'+new Date().toISOString().slice(0,10)+'.json';document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);toast('Copia de seguridad descargada');
}
function importBackup(event){
 const file=event.target.files?.[0];if(!file)return;
 const reader=new FileReader();reader.onload=()=>{try{const raw=JSON.parse(reader.result),incoming=raw.data||raw;
  const required=['topics','done','doubts','sessions','articles','questions','reviews','testResults'];
  if(!incoming||!Array.isArray(incoming.topics)||!Array.isArray(incoming.questions)||!required.every(k=>k in incoming))throw new Error('Formato de copia no reconocido');
  if(!confirm('La restauración sustituirá el progreso y los datos locales actuales. ¿Continuar?'))return;
  data={topics:incoming.topics,done:incoming.done||{},doubts:incoming.doubts||[],sessions:incoming.sessions||[],articles:incoming.articles||[],questions:incoming.questions||[],reviews:incoming.reviews||[],testResults:incoming.testResults||[]};
  localStorage.setItem(KEY,JSON.stringify(data));renderAll();renderLogs();fillQuestionSelects();renderQuestionBank();toast('Copia restaurada correctamente');
 }catch(e){alert('No se pudo restaurar la copia: '+e.message)}finally{event.target.value=''}};reader.readAsText(file);
}
function uid(){return 'x'+Math.random().toString(36).slice(2,10)}function format(s){s=Math.max(0,s|0);return [Math.floor(s/3600),Math.floor(s%3600/60),s%60].map(x=>String(x).padStart(2,'0')).join(':')}function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
document.getElementById('today').textContent=new Date().toLocaleDateString('es-ES',{weekday:'long',day:'numeric',month:'long'});renderAll();fillTopicSelects();fillQuestionSelects();renderReviewPage();
